-- ---------- vendor groups ----------
on conflict (name) do update set manual = excluded.manual,
                                 sort_ord = excluded.sort_ord;

-- ---------- products ----------
on conflict (code) do update set name = excluded.name,
                                 tamil = excluded.tamil,
                                 unit = excluded.unit,
                                 unit_weight_kg = excluded.unit_weight_kg,
                                 alias = excluded.alias;

-- ---------- product -> group ----------
on conflict (product_code) do update set group_name = excluded.group_name;

